  function islandFacadeTex() {
    const S = 128,
      p = new Uint8Array(S * S * 4);
    for (let y = 0; y < S; y++)
      for (let x = 0; x < S; x++) {
        const o = (y * S + x) * 4,
          cx = x % 16,
          cy = y % 16,
          win = cx >= 4 && cx < 12 && cy >= 4 && cy < 12,
          sill = cx >= 3 && cx < 13 && cy === 3,
          line = cy === 0;
        let r = 255,
          g = 255,
          b = 255;
        if (win) {
          const k = cy >= 9 ? 0.9 : 1;
          r = 112 * k;
          g = 160 * k;
          b = 206 * k;
          if (cx === 4 || cx === 11 || cy === 4 || cy === 11) {
            r = g = 250;
            b = 244;
          }
        } else if (sill) {
          r = g = 246;
          b = 236;
        } else if (line) {
          r = 242;
          g = 238;
          b = 230;
        }
        p[o] = r;
        p[o + 1] = g;
        p[o + 2] = b;
        p[o + 3] = 255;
      }
    const t = new T.DataTexture(p, S, S, T.RGBAFormat);
    t.wrapS = t.wrapT = T.RepeatWrapping;
    t.magFilter = T.LinearFilter;
    t.minFilter = T.LinearMipmapLinearFilter;
    t.generateMipmaps = true;
    t.needsUpdate = true;
    return t;
  }
