  function bannerRig(def) {
    const col = hex(tugColour(def)),
      rope = col,
      SEG = 8,
      SIDES = 5,
      tubes = 1 + 3,
      nTube = (SEG + 1) * SIDES,
      poleN = 10,
      TAILS = 4,
      TSEG = 6,
      tailO = tubes * nTube + poleN * 2 + poleN * 6,
      nv = tailO + TAILS * (TSEG + 1) * 2,
      pos = new Float32Array(nv * 3),
      nor = new Float32Array(nv * 3),
      cl = new Float32Array(nv * 4),
      uv = new Float32Array(nv * 2),
      idx = [];
    const tubeIdx = (o) => {
      for (let s = 0; s < SEG; s++)
        for (let k = 0; k < SIDES; k++) {
          const a = o + s * SIDES + k,
            b = o + s * SIDES + ((k + 1) % SIDES);
          idx.push(a, b, a + SIDES, b, b + SIDES, a + SIDES);
        }
    };
    for (let t = 0; t < tubes; t++) {
      tubeIdx(t * nTube);
      for (let i = 0; i < nTube; i++)
        cl.set([...(t === 0 ? rope : rope), 1], (t * nTube + i) * 4);
    }
    const po = tubes * nTube;
    for (let k = 0; k < poleN; k++) {
      const j = (k + 1) % poleN;
      idx.push(
        po + k,
        po + j,
        po + poleN + k,
        po + j,
        po + poleN + j,
        po + poleN + k,
      );
    }
    for (let i = 0; i < poleN * 2; i++) cl.set([...col, 1], (po + i) * 4);
    const bo = po + poleN * 2;
    for (let r = 0; r < 5; r++)
      for (let k = 0; k < poleN; k++) {
        const a = bo + r * poleN + k,
          b = bo + r * poleN + ((k + 1) % poleN);
        idx.push(a, b, a + poleN, b, b + poleN, a + poleN);
      }
    for (let i = 0; i < poleN * 6; i++) cl.set([...col, 1], (bo + i) * 4);
    const nIdx0 = idx.length;
    for (let t = 0; t < TAILS; t++) {
      const o = tailO + t * (TSEG + 1) * 2;
      for (let s = 0; s < TSEG; s++) {
        const a = o + s * 2;
        idx.push(a, a + 2, a + 1, a + 1, a + 2, a + 3);
      }
      for (let i = 0; i < (TSEG + 1) * 2; i++)
        cl.set([0.965, 0.955, 0.925, 1], (o + i) * 4);
    }
    const g = new T.BufferGeometry();
    g.setAttribute(
      "position",
      new T.BufferAttribute(pos, 3).setUsage(T.DynamicDrawUsage),
    );
    g.setAttribute(
      "normal",
      new T.BufferAttribute(nor, 3).setUsage(T.DynamicDrawUsage),
    );
    g.setAttribute("aCol", new T.BufferAttribute(cl, 4));
    g.setAttribute("uv", new T.BufferAttribute(uv, 2));
    g.setIndex(idx);
    g.setDrawRange(0, nIdx0);
    const mesh = new T.Mesh(g, M.lit);
    mesh.frustumCulled = false;
    const A = new T.Vector3(),
      B = new T.Vector3(),
      D = new T.Vector3(),
      U = new T.Vector3(),
      V = new T.Vector3(),
      P = new T.Vector3(),
      ring = new T.Vector3(),
      mid = new T.Vector3(),
      Y = new T.Vector3(0, 1, 0),
      E = new T.Vector3(),
      N = new T.Vector3(),
      F = new T.Vector3(),
      X1 = new T.Vector3();
    const frame = (d) => {
      U.copy(Math.abs(d.y) > 0.9 ? new T.Vector3(1, 0, 0) : Y)
        .cross(d)
        .normalize();
      V.crossVectors(d, U).normalize();
    };
    const tube = (o, a, b, r, sag) => {
      D.subVectors(b, a);
      const L = D.length() || 1;
      D.divideScalar(L);
      frame(D);
      for (let s = 0; s <= SEG; s++) {
        const t = s / SEG;
        P.copy(a).addScaledVector(D, L * t);
        P.y -= sag * 4 * t * (1 - t);
        for (let k = 0; k < SIDES; k++) {
          const an = (k / SIDES) * 2 * PI,
            cx = Math.cos(an),
            sy = Math.sin(an),
            i = o + s * SIDES + k;
          pos[i * 3] = P.x + (U.x * cx + V.x * sy) * r;
          pos[i * 3 + 1] = P.y + (U.y * cx + V.y * sy) * r;
          pos[i * 3 + 2] = P.z + (U.z * cx + V.z * sy) * r;
          nor[i * 3] = U.x * cx + V.x * sy;
          nor[i * 3 + 1] = U.y * cx + V.y * sy;
          nor[i * 3 + 2] = U.z * cx + V.z * sy;
        }
      }
    };
    const update = (hitch, top, bot, ttop, tbot) => {
      mid.addVectors(top, bot).multiplyScalar(0.5);
      D.subVectors(mid, hitch);
      const L = D.length();
      ring.copy(mid).addScaledVector(D.normalize(), -Math.min(24, L * 0.3));
      tube(0, hitch, ring, 0.55, Math.min(5, L * 0.04));
      tube(nTube, ring, top, 0.32, 0.4);
      tube(nTube * 2, ring, mid, 0.32, 0.4);
      tube(nTube * 3, ring, bot, 0.32, 0.4);
      D.subVectors(bot, top);
      const ph = D.length() || 1;
      D.divideScalar(ph);
      frame(D);
      const pr = 1.0;
      for (let e = 0; e < 2; e++) {
        const c = e ? bot : top;
        for (let k = 0; k < poleN; k++) {
          const an = (k / poleN) * 2 * PI,
            cx = Math.cos(an),
            sy = Math.sin(an),
            i = po + e * poleN + k;
          pos[i * 3] =
            c.x + (U.x * cx + V.x * sy) * pr - D.x * (e ? -0.5 : 0.5);
          pos[i * 3 + 1] =
            c.y + (U.y * cx + V.y * sy) * pr - D.y * (e ? -0.5 : 0.5);
          pos[i * 3 + 2] =
            c.z + (U.z * cx + V.z * sy) * pr - D.z * (e ? -0.5 : 0.5);
          nor[i * 3] = U.x * cx + V.x * sy;
          nor[i * 3 + 1] = U.y * cx + V.y * sy;
          nor[i * 3 + 2] = U.z * cx + V.z * sy;
        }
      }
      const br = 2.1;
      for (let r = 0; r < 6; r++) {
        const ph2 = (r / 5) * PI,
          yy = -Math.cos(ph2),
          rr = Math.sin(ph2);
        for (let k = 0; k < poleN; k++) {
          const an = (k / poleN) * 2 * PI,
            cx = Math.cos(an) * rr,
            sy = Math.sin(an) * rr,
            i = bo + r * poleN + k;
          const nx = U.x * cx + V.x * sy + D.x * yy,
            ny = U.y * cx + V.y * sy + D.y * yy,
            nz = U.z * cx + V.z * sy + D.z * yy;
          pos[i * 3] = bot.x + D.x * (br + 0.5) + nx * br;
          pos[i * 3 + 1] = bot.y + D.y * (br + 0.5) + ny * br;
          pos[i * 3 + 2] = bot.z + D.z * (br + 0.5) + nz * br;
          nor[i * 3] = nx;
          nor[i * 3 + 1] = ny;
          nor[i * 3 + 2] = nz;
        }
      }
      if (ttop && tbot) {
        E.subVectors(tbot, ttop);
        const bh = E.length() || 1;
        E.divideScalar(bh);
        F.addVectors(ttop, tbot).multiplyScalar(0.5).sub(mid);
        F.addScaledVector(E, -F.dot(E));
        if (F.lengthSq() < 1e-6) F.set(0, 0, 1);
        F.normalize();
        N.crossVectors(E, F).normalize();
        const tm = rigTime();
        for (let t = 0; t < TAILS; t++) {
          const o = tailO + t * (TSEG + 1) * 2,
            f = (t + 0.5) / TAILS,
            len = bh * (0.32 + (0.16 * ((t * 7) % 4)) / 3),
            w = bh * 0.055;
          X1.copy(ttop).addScaledVector(E, bh * lerp(0.12, 0.88, f));
          for (let k = 0; k <= TSEG; k++) {
            const u = k / TSEG,
              fl =
                Math.sin(tm * 2 * PI * 1.25 - u * 4.2 + t * 1.7) *
                bh *
                0.09 *
                u,
              dn = u * u * bh * 0.06;
            P.copy(X1)
              .addScaledVector(F, len * u)
              .addScaledVector(N, fl)
              .addScaledVector(E, dn);
            for (let e = 0; e < 2; e++) {
              const i = o + k * 2 + e,
                q = (e ? 0.5 : -0.5) * w * (1 - 0.35 * u);
              pos[i * 3] = P.x + E.x * q;
              pos[i * 3 + 1] = P.y + E.y * q;
              pos[i * 3 + 2] = P.z + E.z * q;
              nor[i * 3] = N.x;
              nor[i * 3 + 1] = N.y;
              nor[i * 3 + 2] = N.z;
            }
          }
        }
        g.setDrawRange(0, idx.length);
      } else g.setDrawRange(0, nIdx0);
      g.attributes.position.needsUpdate = true;
      g.attributes.normal.needsUpdate = true;
    };
    return {
      mesh,
      update,
    };
  }
  function chuteGeo() {
    const g = new Geo(true),
      line = hex("#5c6470"),
      cy = hex("#49d6f9"),
      wt = hex("#f6f4ec"),
      jeans = hex("#3d5f99"),
      boot = hex("#f4f4f0");
    acBall(
      g,
      [0, 0.2, 0],
      3.4,
      2.2,
      3.4,
      (ph, th) => (Math.floor((th + PI) / (PI / 4)) % 2 ? cy : wt),
      16,
      8,
      (ph) => ph < 1.5,
    );
    for (const [x, z] of [
      [-2.6, 0],
      [2.6, 0],
      [0, -2.2],
      [0, 2.2],
    ])
      stick(
        g,
        x,
        0,
        z,
        x < 0 ? -0.32 : x > 0 ? 0.32 : 0,
        -3.72,
        z < 0 ? -0.08 : z > 0 ? 0.08 : 0,
        0.07,
        0.07,
        line,
      );
    stick(g, -0.3, -4.22, 0, -0.34, -3.74, 0, 0.13, 0.13, KID.skin);
    stick(g, 0.3, -4.22, 0, 0.34, -3.74, 0, 0.13, 0.13, KID.skin);
    acKid(g, {
      c: [0, -4.12, 0],
      r: 0.27,
      free: true,
    });
    acBall(g, [0, -4.95, 0.02], 0.3, 0.42, 0.22, KID.tee, 10, 6);
    stick(g, -0.12, -5.2, 0, -0.16, -5.7, 0.05, 0.16, 0.16, jeans);
    stick(g, 0.12, -5.2, 0, 0.16, -5.7, -0.05, 0.16, 0.16, jeans);
    acBall(g, [-0.16, -5.78, 0.06], 0.1, 0.08, 0.15, boot, 8, 4);
    acBall(g, [0.16, -5.78, -0.02], 0.1, 0.08, 0.15, boot, 8, 4);
    acSmooth(g, 50);
    return g;
  }
