      let cw = Math.floor(Math.min(w, h * A) + 1e-6),
        ch = Math.round(cw / A);
      if (ch > h) {
        ch = Math.floor(h);
        cw = Math.round(ch * A);
      }
      if (cw < 16 || ch < 9) return false;
      const pw = Math.round(cw * dpr),
        ph = Math.round(ch * dpr),
        rs = resOverride ? clamp(resOverride / ph, 0.1, 1) : 1,
        iw = Math.max(64, Math.round(pw * rs)),
        ih = Math.max(48, Math.round(ph * rs));
