        const j = (i + 1) % n,
          h = (i + n - 1) % n;
        idx.push(
          C,
          W[i],
          W[j],
          W[i],
          V[i],
          W[j],
          W[i],
          V[h],
          Tp[i],
          W[i],
          Tp[i],
          V[i],
        );
